const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright');
const {fixture,ids}=require('./tank-online-fixture.cjs');
const root=path.join(__dirname,'..'),read=file=>fs.readFileSync(path.join(root,file),'utf8');
const origin='https://tank-entry.test';

// Keep the shipped World renderer, game-card handler, wallet update, asset
// loader, bridge and complete Tank iframe. Only authentication and the service
// are local fixtures; all game states are generated by the real local handler.
let world=read('world.html').replace(/<script\b[^>]*\bsrc=[^>]*>\s*<\/script>/g,'')
 .replace('import { screw3d as screwGame } from "./screw3d.js";','const screwGame={};');
world=world.replace('<script type="module">',()=>'<script>'+['world-navigation.js','world-game-assets.js','multiplayer-entry.js'].map(read).join('\n')+'</script><script type="module">');
const boot=world.indexOf('j1(()=>H());gm(');assert.ok(boot>0);
world=world.slice(0,boot)+`
S={functions:{invoke:async(name,{body})=>{
 const data=await tankFixtureInvoke(body);tankEntryFixture.completed.push(body.action);
 return {data,error:null};
}},rpc:async()=>({data:[],error:null})};
D.online=true;D.user={id:'fixture-member'};D.walletReady=true;D.doorReady=true;D.isAdmin=false;
$.me.nick='테스트 플레이어';$.coins=1;
g.tab='place';g.place={id:'arcade',ch:1,count:1,log:[]};
gm(()=>sr.tab({tab:'arcade'}));H();clearInterval(g.placeT);g.placeT=null;
window.tankEntryFixture={completed:[],coins:()=>$.coins};
`+world.slice(world.indexOf('</script>',boot));

(async()=>{
 const service=await fixture();service.holdDeadlines(true);
 const browser=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:['--no-sandbox','--disable-dev-shm-usage']});
 try{
  const cases=[
   {mode:'solo',viewport:{width:707,height:739},actor:ids[0]},
   {mode:'solo',viewport:{width:390,height:844},actor:ids[1]},
   {mode:'solo',viewport:{width:1280,height:800},actor:ids[2]},
   {mode:'local',viewport:{width:390,height:844},actor:ids[3]},
   {mode:'online',viewport:{width:707,height:739},actor:ids[4],friend:ids[5]}
  ];
  for(const {mode,viewport,actor,friend} of cases){
   const context=await browser.newContext({viewport,isMobile:viewport.width<800,hasTouch:viewport.width<800});
   const page=await context.newPage(),errors=[],calls=[];
   page.setDefaultTimeout(10000);page.on('pageerror',error=>errors.push(error.message));
   page.on('dialog',dialog=>dialog.accept());
   await page.exposeFunction('tankFixtureInvoke',async body=>{
    calls.push(body.action);
    const result=await service.call(actor,body);
    assert.equal(result.status,200,`${mode} ${body.action} succeeds against the local service`);
    return result;
   });
   await context.route('**/*',route=>{
    const url=new URL(route.request().url());
    if(url.origin!==origin)return route.abort();
    if(url.pathname==='/world.html')return route.fulfill({contentType:'text/html',body:world});
    const file=path.resolve(root,'.'+url.pathname);
    if(!file.startsWith(root+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile())return route.abort();
    return route.fulfill({path:file,contentType:/\.(mjs|js)$/.test(file)?'text/javascript':/\.css$/.test(file)?'text/css':/\.html$/.test(file)?'text/html':undefined});
   });
   await page.goto(origin+'/world.html');await page.waitForFunction(()=>window.tankEntryFixture);
   const card=page.locator('[data-act="game-open"][data-v="tank"]');
   await card.click();
   const frame=page.frameLocator('.tank-game-dialog iframe');
   const child=()=>page.frames().find(f=>new URL(f.url()).pathname==='/games/tank/index.html');
   async function entry(){
    await frame.locator('#menu').waitFor({state:'visible'});
    await child().waitForFunction(()=>document.body.dataset.mpEntry==='true');
    await page.waitForFunction(()=>document.querySelector('.tank-game-dialog')?.dataset.mpActive==='true');
    assert.equal(await frame.locator('#cv').isVisible(),false,'the entrance hides the battlefield');
   }
   async function playing(){
    await frame.locator('body.in-match').waitFor();
    // Class-only/VM checks missed the entrance stylesheet keeping this overlay
    // visible, which in turn kept its observer and canvas-hiding rules active.
    await frame.locator('#menu').waitFor({state:'hidden',timeout:5000});
    await child().waitForFunction(()=>document.body.dataset.mpEntry==='false');
    await page.waitForFunction(()=>document.querySelector('.tank-game-dialog')?.dataset.mpActive==='false');
    const visible=await child().evaluate(()=>({
     menu:getComputedStyle(document.getElementById('menu')).display,
     canvas:getComputedStyle(document.getElementById('cv')).visibility,
     hasGame:TankOnline.hasGame(),canAim:TankOnline.canAim()
    }));
    assert.deepEqual(visible,{menu:'none',canvas:'visible',hasGame:true,canAim:true});
    assert.equal(await frame.locator('#cv').isVisible(),true,'the actual battlefield is visible');
    await frame.locator('#fire:not([disabled])').waitFor({state:'visible'});
    assert.equal(await frame.locator('#over').isVisible(),false,'no result overlay covers the active game');
   }
   async function close(){
    // The game requests native fullscreen on start. Leave it before clicking
    // World's toolbar, as a browser user can do with its fullscreen control.
    await page.evaluate(async()=>{if(document.fullscreenElement)await document.exitFullscreen();});
    await page.locator('.tank-game-dialog .tour-game-header button').click();
    await page.locator('.tank-game-dialog').waitFor({state:'detached'});
   }
   await frame.locator('#startSolo:not([disabled])').waitFor();await entry();
   async function start(){if(mode==='online'){
    await frame.locator('#onlineMode').click();
    await frame.locator('#roomTitle').fill('로컬 테스트 대전');
    await frame.locator('#createRoom button[type="submit"]').click();
    await frame.locator('#waitingRoom').waitFor();
    const mine=await service.call(actor,{action:'mine'});assert.equal(mine.status,200);
    const joined=await service.join(friend,mine.room);assert.equal(joined.status,200);
    await frame.locator('#startMatch:not([disabled])').waitFor();
    await frame.locator('#startMatch').click();
   }else{
    if(mode==='local')await frame.locator('#localMode').click();
    if(mode==='local')await frame.locator('#localPlayers').selectOption('2');
    else assert.equal(await frame.locator('#soloOpponents').inputValue(),'3','the reported default three-computer setup is preserved');
    await frame.locator(mode==='local'?'#startLocal':'#startSolo').click();
   }}
   await start();
   await playing();
   assert.equal(await page.evaluate(()=>tankEntryFixture.coins()),100,'the real World wallet callback accepts the service response');
   const previous=(await service.call(actor,{action:'mine'})).room.id;
   await close();await card.click();
   await frame.locator('#startSolo:not([disabled])').waitFor();await entry();
   assert.equal(await frame.locator('#resumeMatch').isVisible(),false,'returning starts at a fresh entrance');
   assert.equal((await service.call(actor,{action:'mine'})).room,null,'the previous game was left through the server');
   if(mode==='online'){
    const continuing=await service.call(friend,{action:'read',room_id:previous});assert.equal(continuing.room.status,'active');assert.ok(continuing.room.computerSeats.includes(0),'the other person keeps the inherited match');
    assert.equal((await service.call(friend,{action:'leave',room_id:previous,version:continuing.room.version,request_id:crypto.randomUUID()})).room,null);
   }
   await start();await playing();
   assert.notEqual((await service.call(actor,{action:'mine'})).room.id,previous,'reentry creates a different game');
   if(mode!=='online'){
    await frame.locator('#surrender').click();
    const start=frame.locator(mode==='local'?'#startLocal':'#startSolo');
    await start.waitFor({state:'visible'});await entry();
    await start.click();await playing();
   }
   const angle=await frame.locator('#prot').getAttribute('aria-valuenow');
   await frame.locator('#angleLeft').click();
   assert.notEqual(await frame.locator('#prot').getAttribute('aria-valuenow'),angle,'aim controls receive real pointer clicks');
   await frame.locator('#fire').click();
   await page.waitForFunction(()=>tankEntryFixture.completed.includes('fire'));
   assert.equal(await frame.locator('#menu').isVisible(),false,'firing does not reopen the entrance');
   assert.equal(await frame.locator('#cv').isVisible(),true,'the flight remains visible');
   assert.ok(calls.includes('mine')&&calls.includes('create')&&calls.includes('start')&&calls.includes('fire'));
   assert.deepEqual(errors,[],'no World/bridge/iframe errors');
   await context.close();
   console.log(`PASS: ${mode} ${viewport.width}x${viewport.height}, real World entry, fresh reentry${mode!=='online'?'/return/new game':''}, aim/fire and service response.`);
  }
 }finally{await browser.close();await service.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});
